using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEditor;using UnityEditor.SceneManagement;using DeliveryRider;using Newtonsoft.Json.Linq;
public static class MyeongjiEveningSetup {
 const string Folder="Assets/_Game/Art/Myeongji/StreetDetails";
 static GameObject Map=>SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name=="MyeongjiMap");
 static void Guard(){var scene=SceneManager.GetActiveScene();if(EditorApplication.isPlaying||scene.isDirty||!scene.path.EndsWith("FourDistrictPrototype_Myeongji.unity"))throw new Exception("Saved map edit scene required");}
 static void Save(){AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());}
 static Material Template(string name,string source){string path=Folder+"/"+name+".mat";var material=AssetDatabase.LoadAssetAtPath<Material>(path);if(material!=null)return material;material=new Material(Map.GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).First(m=>m!=null&&m.name==source)){name=name};material.EnableKeyword("_EMISSION");material.SetColor("_EmissionColor",Color.black);material.globalIlluminationFlags=MaterialGlobalIlluminationFlags.None;AssetDatabase.CreateAsset(material,path);return material;}
 static string Key(Vector3 v)=>Mathf.RoundToInt(v.x*10000)+","+Mathf.RoundToInt(v.y*10000)+","+Mathf.RoundToInt(v.z*10000);
 class Pane {public List<int> triangles=new List<int>();public HashSet<string> points=new HashSet<string>();public float bottom=1000,top=-1000,lo=1000,hi=-1000;}
 static string Windows(int start,int count){Guard();var material=Template("Evening_Window_Base","KIT_DistrictGlass_445E69");if(!AssetDatabase.IsValidFolder(Folder+"/Windows"))AssetDatabase.CreateFolder(Folder,"Windows");var lots=(JArray)JObject.Parse(File.ReadAllText("Docs/MapLayout/Myeongji/layout.json"))["lots"];int buildings=0,panes=0;var report=new List<string>();foreach(var lot in lots.Skip(start).Take(count)){string id=(string)lot[0];var r=Map.GetComponentsInChildren<MeshRenderer>().Single(v=>v.name=="AB01_"+id+".001");string path=Folder+"/Windows/"+id+"_Evening.asset";if(AssetDatabase.LoadAssetAtPath<Mesh>(path)!=null)throw new Exception("Already installed "+id);var f=r.GetComponent<MeshFilter>();var source=f.sharedMesh;var vs=source.vertices.Select(v=>r.transform.TransformPoint(v)).ToArray();int rot=(int)lot[7];var n=rot==0?Vector3.back:rot==180?Vector3.forward:rot==90?Vector3.right:Vector3.left;var u=Mathf.Abs(n.z)>.5f?Vector3.right:Vector3.forward;var indices=Enumerable.Range(0,source.subMeshCount).Select(i=>source.GetTriangles(i)).ToArray();var removed=new Dictionary<int,HashSet<int>>();var glowing=new List<int>();int selected=0;
 for(int sub=0;sub<source.subMeshCount;sub++){if(r.sharedMaterials[sub].name.IndexOf("Glass",StringComparison.OrdinalIgnoreCase)<0)continue;var idx=indices[sub];var parts=new List<Pane>();for(int i=0;i<idx.Length;i+=3){var a=vs[idx[i]];var b=vs[idx[i+1]];var c=vs[idx[i+2]];if(Mathf.Min(a.y,Mathf.Min(b.y,c.y))<3.4f||Vector3.Dot(Vector3.Cross(b-a,c-a).normalized,n)<.98f)continue;var part=new Pane();part.triangles.Add(i);foreach(var v in new[]{a,b,c}){part.points.Add(Key(v));part.bottom=Mathf.Min(part.bottom,v.y);part.top=Mathf.Max(part.top,v.y);part.lo=Mathf.Min(part.lo,Vector3.Dot(v,u));part.hi=Mathf.Max(part.hi,Vector3.Dot(v,u));}parts.Add(part);}
 var merged=new List<Pane>();while(parts.Count>0){var p=parts[0];parts.RemoveAt(0);bool found=true;while(found){found=false;for(int k=parts.Count-1;k>=0;k--)if(p.points.Overlaps(parts[k].points)){var q=parts[k];p.points.UnionWith(q.points);p.triangles.AddRange(q.triangles);p.bottom=Mathf.Min(p.bottom,q.bottom);p.top=Mathf.Max(p.top,q.top);p.lo=Mathf.Min(p.lo,q.lo);p.hi=Mathf.Max(p.hi,q.hi);parts.RemoveAt(k);found=true;}}if(p.hi-p.lo>.25f&&p.top-p.bottom>.3f)merged.Add(p);}
 var ordered=merged.OrderBy(p=>p.bottom).ThenBy(p=>p.lo).ToArray();int seed=id.Sum(ch=>(int)ch);for(int i=0;i<ordered.Length;i++){if((i+seed)%3!=0||selected>=3)continue;var p=ordered[i];if(!removed.ContainsKey(sub))removed.Add(sub,new HashSet<int>());foreach(var tri in p.triangles){removed[sub].Add(tri);glowing.AddRange(new[]{idx[tri],idx[tri+1],idx[tri+2]});}selected++;}}
 if(selected==0){report.Add(id+": no suitable upper pane, original retained");continue;}var mesh=UnityEngine.Object.Instantiate(source);mesh.name=id+"_Evening";mesh.subMeshCount=source.subMeshCount+1;for(int sub=0;sub<source.subMeshCount;sub++){if(!removed.TryGetValue(sub,out var cut))continue;var keep=new List<int>();var idx=indices[sub];for(int i=0;i<idx.Length;i+=3)if(!cut.Contains(i))keep.AddRange(new[]{idx[i],idx[i+1],idx[i+2]});mesh.SetTriangles(keep,sub);}mesh.SetTriangles(glowing,source.subMeshCount);mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,path);f.sharedMesh=mesh;var col=r.GetComponent<MeshCollider>();col.sharedMesh=mesh;r.sharedMaterials=r.sharedMaterials.Concat(new[]{material}).ToArray();PrefabUtility.RecordPrefabInstancePropertyModifications(f);PrefabUtility.RecordPrefabInstancePropertyModifications(col);PrefabUtility.RecordPrefabInstancePropertyModifications(r);buildings++;panes+=selected;report.Add(id+": "+selected+" upper panes, geometry unchanged");}
 Save();File.AppendAllLines("Docs/MapLayout/Myeongji/evening_windows.txt",report);return "Buildings "+buildings+", selected windows "+panes;}
 public static string WindowsFirst()=>Windows(0,26);
 public static string WindowsSecond()=>Windows(26,26);
 public static string Connect(){Guard();if(Map.transform.Find("EveningLighting")!=null)throw new Exception("Already connected");var root=new GameObject("EveningLighting");root.transform.SetParent(Map.transform,true);var controller=root.AddComponent<NeighborhoodEveningLights>();var windows=new List<(Renderer r,int slot,int phase)>();var lamps=new List<(Renderer r,int slot,int phase)>();var lights=new List<Light>();var template=Template("Evening_Lamp_Base","ST_Lamp");foreach(var r in Map.GetComponentsInChildren<MeshRenderer>()){var mats=r.sharedMaterials;for(int i=0;i<mats.Length;i++)if(mats[i].name=="Evening_Window_Base")windows.Add((r,i,r.name.Sum(c=>(int)c)%4));if(!r.name.StartsWith("StreetLamp_"))continue;int slot=Array.FindIndex(mats,m=>m.name=="ST_Lamp");if(slot<0)continue;var mesh=r.GetComponent<MeshFilter>().sharedMesh;var v=mesh.GetTriangles(slot).Distinct().Select(i=>r.transform.TransformPoint(mesh.vertices[i])).ToArray();var center=v.Aggregate(Vector3.zero,(a,b)=>a+b)/v.Length;float bottom=v.Min(p=>p.y);var host=new GameObject(r.name+"_Light");host.transform.SetParent(root.transform,true);host.transform.SetPositionAndRotation(new Vector3(center.x,bottom-.035f,center.z),Quaternion.Euler(90,0,0));var light=host.AddComponent<Light>();light.type=LightType.Spot;light.range=8f;light.spotAngle=100;light.innerSpotAngle=65;light.color=new Color(1,.83f,.60f);light.intensity=0;light.shadows=LightShadows.None;light.enabled=false;lights.Add(light);mats[slot]=template;r.sharedMaterials=mats;PrefabUtility.RecordPrefabInstancePropertyModifications(r);lamps.Add((r,slot,0));}
 var so=new SerializedObject(controller);so.FindProperty("windowMaterial").objectReferenceValue=Template("Evening_Window_Base","KIT_DistrictGlass_445E69");so.FindProperty("lampMaterial").objectReferenceValue=template;
 void Bind(string name,List<(Renderer r,int slot,int phase)> data){var a=so.FindProperty(name);a.arraySize=data.Count;for(int i=0;i<data.Count;i++){var p=a.GetArrayElementAtIndex(i);p.FindPropertyRelative("renderer").objectReferenceValue=data[i].r;p.FindPropertyRelative("slot").intValue=data[i].slot;p.FindPropertyRelative("group").intValue=data[i].phase;}}
 Bind("windows",windows);Bind("lamps",lamps);var array=so.FindProperty("streetLights");array.arraySize=lights.Count;for(int i=0;i<lights.Count;i++)array.GetArrayElementAtIndex(i).objectReferenceValue=lights[i];so.ApplyModifiedPropertiesWithoutUndo();
 var rp=GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;if(rp!=null){var settings=new SerializedObject(rp);settings.FindProperty("m_AdditionalLightsRenderingMode").intValue=2;settings.FindProperty("m_AdditionalLightsPerObjectLimit").intValue=8;settings.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(rp);}
 Save();return "Window groups "+windows.Count+", lamps "+lamps.Count+", nearby shadowless light budget 8";}
}
